+// distributed under the License is distributed on an "AS IS" BASIS,
+// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+// See the License for the specific language governing permissions and
+// limitations under the License.
+
+#include "diag.h"
+
+#import <Foundation/Foundation.h>
+#import <LocalAuthentication/LocalAuthentication.h>
+#import <Security/Security.h>
+
+uint32_t TouchIDDiag(void) {
+  uint32_t checks = 0;
+
+  SecCodeRef code = NULL;
+  if (SecCodeCopySelf(kSecCSDefaultFlags, &code) == errSecSuccess) {
+    if (SecCodeCheckValidity(code, kSecCSBasicValidateOnly, NULL) == errSecSuccess) {
+      checks |= 1;
+    }
+
+    CFDictionaryRef signingInfo = NULL;
+    if (SecCodeCopySigningInformation(code, kSecCSSigningInformation,
+                                      &signingInfo) == errSecSuccess) {
+      NSDictionary *info = (__bridge NSDictionary *)signingInfo;
+      NSDictionary *entitlements = info[(__bridge id)kSecCodeInfoEntitlementsDict];
+      if ([entitlements[@"com.apple.application-identifier"] isKindOfClass:[NSString class]] &&
+          [entitlements[@"keychain-access-groups"] isKindOfClass:[NSArray class]]) {
+        checks |= 2;
+      }
+      CFRelease(signingInfo);
+    }
+    CFRelease(code);
+  }
+
+  LAContext *context = [[LAContext alloc] init];
+  if ([context canEvaluatePolicy:LAPolicyDeviceOwnerAuthenticationWithBiometrics
+                           error:NULL]) {
+    checks |= 4;
+  }
+
+  // Use the same key attributes as registration, then remove the test key.
+  CFErrorRef error = NULL;
+  SecAccessControlRef access = SecAccessControlCreateWithFlags(
+      kCFAllocatorDefault, kSecAttrAccessibleWhenUnlockedThisDeviceOnly,
+      kSecAccessControlPrivateKeyUsage | kSecAccessControlBiometryAny, &error);
+  if (access != NULL) {
+    NSData *tag = [[[NSUUID UUID] UUIDString] dataUsingEncoding:NSUTF8StringEncoding];
+    NSDictionary *attributes = @{
+      (id)kSecAttrKeyType : (id)kSecAttrKeyTypeECSECPrimeRandom,
+      (id)kSecAttrKeySizeInBits : @256,
+      (id)kSecAttrTokenID : (id)kSecAttrTokenIDSecureEnclave,
+      (id)kSecPrivateKeyAttrs : @{
+        (id)kSecAttrIsPermanent : @YES,
+        (id)kSecAttrAccessControl : (__bridge id)access,
+        (id)kSecAttrApplicationTag : tag,
+      },
+    };
+    SecKeyRef key = SecKeyCreateRandomKey((__bridge CFDictionaryRef)attributes, &error);
+    if (key != NULL) {
+      checks |= 8;
+      CFRelease(key);
+      NSDictionary *query = @{
+        (id)kSecClass : (id)kSecClassKey,
+        (id)kSecAttrKeyType : (id)kSecAttrKeyTypeECSECPrimeRandom,
+        (id)kSecAttrApplicationTag : tag,
+      };
+      SecItemDelete((__bridge CFDictionaryRef)query);
+    }
+    CFRelease(access);
+  }
+  if (error != NULL) {
+    CFRelease(error);
+  }
+
+  return checks;
+}

